/*
 * High-performance portfolio calculations using a C extension.
 *
 *   risk   = sqrt(x^T * S * x)
 *   return = x^T * r
 *
 * Both kernels accumulate in exactly the same order as portfolio_baseline.py,
 * so the results agree with the pure-Python reference well within 1e-10.
 *
 * Two input paths are provided:
 *   1. NumPy arrays are used in place (zero copy) when they are already
 *      float64 / C-contiguous; otherwise NumPy converts them.
 *   2. Plain Python sequences (lists or tuples, e.g. a list of row lists) are
 *      flattened straight into a contiguous double buffer with a tight C
 *      loop.  That is much faster than the generic NumPy object-array
 *      conversion for the large matrices handled here.
 */

#define NPY_NO_DEPRECATED_API NPY_1_7_API_VERSION
#include <Python.h>
#include <numpy/arrayobject.h>
#include <math.h>
#include <stdint.h>
#include <stdlib.h>

/* Requirements for a buffer we are allowed to read as double* directly. */
#define ARRAY_REQUIREMENTS \
    (NPY_ARRAY_C_CONTIGUOUS | NPY_ARRAY_ALIGNED | NPY_ARRAY_NOTSWAPPED)

/*
 * A float64 buffer used by the kernels.  It either points straight into a
 * NumPy array we hold a reference to (zero-copy path) or into memory we
 * allocate while flattening a Python sequence.
 */
typedef struct {
    double *data;
    PyArrayObject *owner;   /* strong reference, or NULL when data is malloc'ed */
    npy_intp size;          /* number of elements */
    npy_intp rows, cols;    /* matrix shape (cols == 0 for vectors) */
    int is_malloc;
} DoubleBuffer;

static void db_clear(DoubleBuffer *b)
{
    if (b->owner != NULL) {
        Py_DECREF(b->owner);
        b->owner = NULL;
    }
    if (b->is_malloc && b->data != NULL) {
        free(b->data);
    }
    b->data = NULL;
    b->is_malloc = 0;
    b->size = 0;
    b->rows = 0;
    b->cols = 0;
}

static int is_plain_sequence(PyObject *o)
{
    return PyList_Check(o) || PyTuple_Check(o);
}

static Py_ssize_t plain_seq_len(PyObject *o)
{
    return PyList_Check(o) ? PyList_GET_SIZE(o) : PyTuple_GET_SIZE(o);
}

static PyObject *plain_seq_get(PyObject *o, Py_ssize_t i)
{
    return PyList_Check(o) ? PyList_GET_ITEM(o, i) : PyTuple_GET_ITEM(o, i);
}

/*
 * Convert any array-like object with NumPy.  Already-conforming arrays are
 * only referenced, not copied.  Returns 1 on success, -1 on error.
 */
static int db_from_array(PyObject *obj, DoubleBuffer *b, int ndim)
{
    PyArrayObject *arr;

    arr = (PyArrayObject *)PyArray_FROM_OTF(obj, NPY_DOUBLE,
                                            ARRAY_REQUIREMENTS);
    if (arr == NULL)
        return -1;
    if (PyArray_NDIM(arr) != ndim) {
        int got = PyArray_NDIM(arr);
        Py_DECREF(arr);
        PyErr_Format(PyExc_ValueError,
                     "expected a %d-dimensional array, got %d", ndim, got);
        return -1;
    }

    b->data = (double *)PyArray_DATA(arr);
    b->owner = arr;
    b->is_malloc = 0;
    b->size = PyArray_SIZE(arr);
    if (ndim == 2) {
        b->rows = PyArray_DIM(arr, 0);
        b->cols = PyArray_DIM(arr, 1);
    } else {
        b->rows = b->size;
        b->cols = 0;
    }
    return 1;
}

/*
 * Flatten a 1-D Python sequence holding float objects.
 * Returns 1 on success, 0 if the object is not such a sequence (caller falls
 * back to NumPy), -1 on error.
 */
static int db_from_float_vector(PyObject *obj, DoubleBuffer *b)
{
    Py_ssize_t n, i;
    double *buf;

    if (!is_plain_sequence(obj))
        return 0;

    n = plain_seq_len(obj);
    buf = (double *)malloc(sizeof(double) * (size_t)(n > 0 ? n : 1));
    if (buf == NULL) {
        PyErr_NoMemory();
        return -1;
    }
    for (i = 0; i < n; i++) {
        PyObject *item = plain_seq_get(obj, i);
        if (!PyFloat_CheckExact(item)) {   /* ints / numpy scalars: let NumPy do it */
            free(buf);
            return 0;
        }
        buf[i] = PyFloat_AS_DOUBLE(item);
    }

    b->data = buf;
    b->owner = NULL;
    b->is_malloc = 1;
    b->size = (npy_intp)n;
    b->rows = (npy_intp)n;
    b->cols = 0;
    return 1;
}

/*
 * Flatten a square 2-D Python sequence of float objects.
 * Returns 1 on success, 0 on decline, -1 on error.
 */
static int db_from_float_matrix(PyObject *obj, DoubleBuffer *b)
{
    Py_ssize_t n, i, j;
    double *buf;

    if (!is_plain_sequence(obj))
        return 0;

    n = plain_seq_len(obj);
    if (n > 0 && (size_t)n > SIZE_MAX / sizeof(double) / (size_t)n) {
        PyErr_SetString(PyExc_OverflowError, "matrix is too large");
        return -1;
    }
    buf = (double *)malloc(sizeof(double) * (size_t)n *
                           (size_t)(n > 0 ? n : 1));
    if (buf == NULL) {
        PyErr_NoMemory();
        return -1;
    }

    for (i = 0; i < n; i++) {
        PyObject *row = plain_seq_get(obj, i);
        double *dst;

        if (!is_plain_sequence(row) || plain_seq_len(row) != n) {
            free(buf);              /* ragged input: reconstruct via NumPy */
            return 0;
        }
        dst = buf + (size_t)i * (size_t)n;
        for (j = 0; j < n; j++) {
            PyObject *item = plain_seq_get(row, j);
            if (!PyFloat_CheckExact(item)) {
                free(buf);
                return 0;
            }
            dst[j] = PyFloat_AS_DOUBLE(item);
        }
    }

    b->data = buf;
    b->owner = NULL;
    b->is_malloc = 1;
    b->size = (npy_intp)n * (npy_intp)n;
    b->rows = (npy_intp)n;
    b->cols = (npy_intp)n;
    return 1;
}

/* Obtain a readable 1-D buffer.  Returns 0 on success, -1 on error. */
static int get_vector(PyObject *obj, DoubleBuffer *b)
{
    int rc;

    db_clear(b);
    if (PyArray_Check(obj))
        rc = db_from_array(obj, b, 1);
    else {
        rc = db_from_float_vector(obj, b);
        if (rc == 0)
            rc = db_from_array(obj, b, 1);
    }
    return rc < 0 ? -1 : 0;
}

/* Obtain a readable 2-D buffer.  Returns 0 on success, -1 on error. */
static int get_matrix(PyObject *obj, DoubleBuffer *b)
{
    int rc;

    db_clear(b);
    if (PyArray_Check(obj))
        rc = db_from_array(obj, b, 2);
    else {
        rc = db_from_float_matrix(obj, b);
        if (rc == 0)
            rc = db_from_array(obj, b, 2);
    }
    return rc < 0 ? -1 : 0;
}

/*
 * sqrt(x^T * S * x), evaluated exactly like the Python baseline: an inner
 * loop over j accumulates S[i][j] * x[j], then x[i] * row_sum is added to the
 * running total.  S is row-major (n x n), x has n elements.
 */
static double risk_kernel(const double *S, const double *x, npy_intp n)
{
    double risk_squared = 0.0;
    npy_intp i, j;

    for (i = 0; i < n; i++) {
        const double *row = S + (size_t)i * (size_t)n;
        double row_sum = 0.0;

        for (j = 0; j < n; j++)
            row_sum += row[j] * x[j];
        risk_squared += x[i] * row_sum;
    }
    return sqrt(risk_squared);
}

/* x^T * r, accumulated in the same order as the Python baseline. */
static double return_kernel(const double *x, const double *r, npy_intp n)
{
    double total = 0.0;
    npy_intp i;

    for (i = 0; i < n; i++)
        total += x[i] * r[i];
    return total;
}

static PyObject *portfolio_risk_c(PyObject *self, PyObject *args)
{
    PyObject *weights_obj, *cov_obj;
    DoubleBuffer x, S;
    npy_intp n;
    double risk;

    (void)self;

    if (!PyArg_ParseTuple(args, "OO:portfolio_risk_c",
                          &weights_obj, &cov_obj))
        return NULL;

    if (get_vector(weights_obj, &x) < 0)
        return NULL;
    if (get_matrix(cov_obj, &S) < 0) {
        db_clear(&x);
        return NULL;
    }

    n = x.size;
    if (S.rows != n || S.cols != n) {
        PyErr_Format(PyExc_ValueError,
                     "cov_matrix must be %" NPY_INTP_FMT "x%" NPY_INTP_FMT
                     ", got %" NPY_INTP_FMT "x%" NPY_INTP_FMT,
                     n, n, S.rows, S.cols);
        db_clear(&x);
        db_clear(&S);
        return NULL;
    }

    Py_BEGIN_ALLOW_THREADS
    risk = risk_kernel(S.data, x.data, n);
    Py_END_ALLOW_THREADS

    db_clear(&x);
    db_clear(&S);
    return PyFloat_FromDouble(risk);
}

static PyObject *portfolio_return_c(PyObject *self, PyObject *args)
{
    PyObject *weights_obj, *returns_obj;
    DoubleBuffer x, r;
    double total;

    (void)self;

    if (!PyArg_ParseTuple(args, "OO:portfolio_return_c",
                          &weights_obj, &returns_obj))
        return NULL;

    if (get_vector(weights_obj, &x) < 0)
        return NULL;
    if (get_vector(returns_obj, &r) < 0) {
        db_clear(&x);
        return NULL;
    }

    if (x.size != r.size) {
        PyErr_Format(PyExc_ValueError,
                     "weights and expected_returns must have the same length "
                     "(%" NPY_INTP_FMT " != %" NPY_INTP_FMT ")",
                     x.size, r.size);
        db_clear(&x);
        db_clear(&r);
        return NULL;
    }

    Py_BEGIN_ALLOW_THREADS
    total = return_kernel(x.data, r.data, x.size);
    Py_END_ALLOW_THREADS

    db_clear(&x);
    db_clear(&r);
    return PyFloat_FromDouble(total);
}

static PyMethodDef module_methods[] = {
    {"portfolio_risk_c", portfolio_risk_c, METH_VARARGS,
     "Calculate portfolio risk: sqrt(x^T * S * x)"},
    {"portfolio_return_c", portfolio_return_c, METH_VARARGS,
     "Calculate portfolio return: x^T * r"},
    {NULL, NULL, 0, NULL}
};

static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT,
    "portfolio_optimized_c",
    "Optimized portfolio calculations",
    -1,
    module_methods
};

PyMODINIT_FUNC PyInit_portfolio_optimized_c(void)
{
    import_array();  /* Initialize NumPy C API */
    return PyModule_Create(&moduledef);
}
