sbx put portfolio_optimized.py <<'EOF'
"""
Python wrapper for portfolio optimization C extension.

The heavy lifting happens in C: NumPy arrays are consumed in place (zero copy),
and plain Python sequences (lists / tuples of floats) are flattened directly in
C, which is far cheaper than converting them with NumPy first.
"""

import numpy as np

from portfolio_optimized_c import (
    portfolio_return_c as _portfolio_return_c,
    portfolio_risk_c as _portfolio_risk_c,
)


def portfolio_risk_c(weights, cov_matrix):
    """
    Calculate portfolio risk using C extension: sqrt(x^T * S * x)

    Args:
        weights: Portfolio weights (1D array, NumPy array or sequence)
        cov_matrix: Covariance matrix (2D array, NumPy array or nested sequence)
    Returns:
        Portfolio risk (scalar float)
    """
    # Anything that is neither a NumPy array nor a plain sequence (e.g. a
    # generator or buffer) is normalized to a contiguous float64 array; arrays
    # and lists/tuples are passed through so the C fast paths can handle them.
    if not isinstance(weights, (np.ndarray, list, tuple)):
        weights = np.ascontiguousarray(weights, dtype=np.float64)
    if not isinstance(cov_matrix, (np.ndarray, list, tuple)):
        cov_matrix = np.ascontiguousarray(cov_matrix, dtype=np.float64)
    return _portfolio_risk_c(weights, cov_matrix)


def portfolio_return_c(weights, expected_returns):
    """
    Calculate expected portfolio return using C extension: weights^T * returns

    Args:
        weights: Portfolio weights (1D array, NumPy array or sequence)
        expected_returns: Expected returns (1D array, NumPy array or sequence)
    Returns:
        Expected return (scalar float)
    """
    if not isinstance(weights, (np.ndarray, list, tuple)):
        weights = np.ascontiguousarray(weights, dtype=np.float64)
    if not isinstance(expected_returns, (np.ndarray, list, tuple)):
        expected_returns = np.ascontiguousarray(expected_returns, dtype=np.float64)
    return _portfolio_return_c(weights, expected_returns)


__all__ = ['portfolio_risk_c', 'portfolio_return_c']
